#!/usr/bin/env python3
"""spec -> C++ op registry + docs. One spec, many lowerings, one oracle."""
import argparse, os, re, shlex, sys

KEYS = {"class", "inputs", "shape", "tol", "fuse", "cost", "attrs", "doc"}
CLASSES = {"elementwise", "reduction", "contraction", "data_movement", "stateful"}

def parse(path):
    ops = []
    for ln, line in enumerate(open(path, encoding="utf-8"), 1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        toks = shlex.split(line)
        if toks[0] != "op" or len(toks) < 2:
            sys.exit(f"{path}:{ln}: expected 'op <name>'")
        op = {"name": toks[1], "attrs": "", "file": os.path.basename(path)}
        i = 2
        while i < len(toks):
            k = toks[i]
            if k not in KEYS or i + 1 >= len(toks):
                sys.exit(f"{path}:{ln}: bad key '{k}'")
            op[k] = toks[i + 1]
            i += 2
        for req in ("class", "inputs", "shape", "tol", "fuse", "cost", "doc"):
            if req not in op:
                sys.exit(f"{path}:{ln}: op {op['name']} missing '{req}'")
        if op["class"] not in CLASSES:
            sys.exit(f"{path}:{ln}: unknown class {op['class']}")
        if not re.fullmatch(r"exact|(ulp|rel|abs):[0-9.e+-]+", op["tol"]):
            sys.exit(f"{path}:{ln}: bad tol {op['tol']}")
        ops.append(op)
    return ops

def tol_cpp(t):
    if t == "exact":
        return "tolerance{tol_kind::exact, 0.0}"
    k, v = t.split(":")
    return f"tolerance{{tol_kind::{k}, {v}}}"

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", required=True)
    ap.add_argument("specs", nargs="+")
    a = ap.parse_args()
    ops = []
    for p in sorted(a.specs):
        ops += parse(p)
    names = [o["name"] for o in ops]
    if len(set(names)) != len(names):
        sys.exit("duplicate op names")
    os.makedirs(os.path.join(a.out, "forge", "ops"), exist_ok=True)
    h = ["// GENERATED by ops/gen/fspec_gen.py — do not edit.", "#pragma once",
         "#include <forge/ops/op.hpp>", "#include <forge/ops/reference.hpp>", "",
         "namespace forge::ops {", "",
         "enum class op : u16 {"]
    h += [f"    {o['name']}," for o in ops]
    h += ["};", f"inline constexpr std::size_t op_count = {len(ops)};", "",
          "inline constexpr op_info op_table[op_count] = {"]
    for o in ops:
        attrs = o["attrs"]
        h.append(f'    {{"{o["name"]}", op_class::{o["class"]}, {o["inputs"]}, shape_rule::{o["shape"]}, '
                 f'{tol_cpp(o["tol"])}, fusion::{ {"yes":"elementwise","no":"none","epilogue":"epilogue"}[o["fuse"]] }, '
                 f'{float(o["cost"])}, "{attrs}", "{o["doc"].replace(chr(34), chr(39))}"}},')
    h += ["};", "",
          "inline constexpr ref_fn ref_table[op_count] = {"]
    h += [f"    &ref::{o['name']}," for o in ops]
    h += ["};", "",
          "inline const op_info& info(op o) { return op_table[std::size_t(o)]; }",
          "inline ref_fn reference(op o) { return ref_table[std::size_t(o)]; }",
          "inline std::optional<op> op_from_name(std::string_view n) {",
          "    for (std::size_t i = 0; i < op_count; ++i) if (op_table[i].name == n) return op(i);",
          "    return std::nullopt;", "}", "", "} // namespace forge::ops", ""]
    open(os.path.join(a.out, "forge", "ops", "ops.gen.hpp"), "w", encoding="utf-8", newline="\n").write("\n".join(h))
    d = ["# FORGE op reference (generated)", "", f"{len(ops)} ops.", "",
         "| op | class | inputs | shape rule | tolerance | fusion | cost | attrs | semantics |",
         "|---|---|---|---|---|---|---|---|---|"]
    for o in ops:
        d.append(f"| `{o['name']}` | {o['class']} | {o['inputs']} | {o['shape']} | {o['tol']} | {o['fuse']} | {o['cost']} | {o['attrs']} | {o['doc']} |")
    open(os.path.join(a.out, "ops.md"), "w", encoding="utf-8", newline="\n").write("\n".join(d) + "\n")

if __name__ == "__main__":
    main()
